-- EEES-DB-005: approved
-- owner: Human Resources
-- rollback: forward-only; las asignaciones se corrigen con una migracion posterior.
-- Fuente: Copia de Ciclo de Turnos DAND 16-09-26.xlsx; se excluye el duplicado de 12.579.300-2 cuyo contrato ENAEX no coincide con su ficha activa CODELCO.
begin;

alter table public.hr_shift_patterns add column if not exists workday_labels text[];

create or replace function public.get_hr_roster_setup_catalogs()
returns jsonb
language plpgsql
security definer
set search_path = public
as $function$
declare current_user_id uuid := auth.uid();
begin
  if not public.user_can_manage_hr_roster(current_user_id) then raise exception 'Sin permisos para administrar jornadas y turnos'; end if;
  return jsonb_build_object('patterns', coalesce((select jsonb_agg(jsonb_build_object('id',hp.id,'code',hp.code,'name',hp.name,'description',hp.description,'working_days',hp.working_days,'resting_days',hp.resting_days,'cycle_length',hp.cycle_length,'color_hex',hp.color_hex,'workday_labels',hp.workday_labels,'is_active',hp.is_active,'created_at',hp.created_at) order by hp.is_active desc,hp.name) from public.hr_shift_patterns hp),'[]'::jsonb), 'exception_types', jsonb_build_array(jsonb_build_object('value','vacation','label',public.get_hr_roster_exception_type_label('vacation')),jsonb_build_object('value','medical_leave','label',public.get_hr_roster_exception_type_label('medical_leave')),jsonb_build_object('value','absent','label',public.get_hr_roster_exception_type_label('absent')),jsonb_build_object('value','extra_shift','label',public.get_hr_roster_exception_type_label('extra_shift')),jsonb_build_object('value','training','label',public.get_hr_roster_exception_type_label('training')),jsonb_build_object('value','administrative_leave','label',public.get_hr_roster_exception_type_label('administrative_leave')),jsonb_build_object('value','union_leave','label',public.get_hr_roster_exception_type_label('union_leave'))));
end;
$function$;

revoke all on function public.get_hr_roster_setup_catalogs() from public,anon,authenticated;
grant execute on function public.get_hr_roster_setup_catalogs() to authenticated;
notify pgrst, 'reload schema';

