resolved as (select distinct on (s.rut) s.*,e.buk_employee_id,e.full_name,coalesce(e.document_type,'rut') as document_type,e.document_number,e.job_title,e.contract_code,e.area_name,p.id as pattern_id from source s join public.employees_active_current e on upper(regexp_replace(coalesce(e.document_number,''),'[^0-9K]','','g'))=upper(regexp_replace(s.rut,'[^0-9K]','','g')) and lower(trim(coalesce(e.area_name,''))) like lower(trim(s.expected_contract)) || '%' join public.hr_shift_patterns p on p.code='dand_'||s.cycle||'_'||s.mode and p.is_active order by s.rut),
inserted as (insert into public.hr_worker_rosters (employee_buk_employee_id,employee_document_type,employee_document_number,employee_full_name,employee_job_title,contract_code,area_name,pattern_id,start_date,end_date,notes,assigned_by) select r.buk_employee_id,r.document_type,r.document_number,r.full_name,r.job_title,r.contract_code,r.area_name,r.pattern_id,r.start_date,null,'Importacion DAND desde Copia de Ciclo de Turnos DAND 16-09-26.xlsx. Observacion: '||r.observation,null from resolved r where not exists (select 1 from public.hr_worker_rosters existing where existing.employee_buk_employee_id=r.buk_employee_id and existing.start_date=r.start_date) returning id)
select count(*) as inserted_assignments from inserted;

